/* ============================================================ alert settings, users, settings, sign in, lock and the phone's own states */
const AlertSettings = { components: { Header, Icon, Toggle, Sheet, Btn },
  setup() {
    const rules = [['low', 'Low stock', 'When a product is at or below its warning level'], ['undo', 'Requests for you', 'Undo a sale, change a payment, expenses, counts'], ['gaps', 'Count gaps', 'When a day closes with a gap'], ['late', 'Late deliveries', 'When a supplier bill is past due'], ['cust', 'Customers who owe', 'A reminder SMS to the customer']];
    const n = computed(() => Math.ceil(S.tmpl.length / 160));
    return { S, rules, n, toast };
  },
  template: `<div class="flex min-h-0 flex-1 flex-col"><Header title="Alerts and reminders"/>
    <div class="scroll min-h-0 flex-1 overflow-y-auto"><div class="space-y-4 p-3 pb-8"><p class="px-1 text-sm text-muted-foreground">In app is always on. Pick what else reaches you.</p>
      <div class="overflow-hidden rounded-xl border bg-card"><div class="grid grid-cols-[1fr_44px_44px] items-center gap-2 border-b px-3.5 py-2 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground"><span>Alert</span><span class="text-center">SMS</span><span class="text-center">Email</span></div>
        <div v-for="(r, i) in rules" :key="r[0]" :class="['grid grid-cols-[1fr_44px_44px] items-center gap-2 px-3.5 py-2.5', i ? 'border-t' : '']"><span class="min-w-0"><span class="block text-sm font-medium">{{ r[1] }}</span><span class="block text-xs text-muted-foreground">{{ r[2] }}</span></span>
          <span class="grid place-items-center"><Toggle :model-value="!!S.ch[r[0]][0]" :label="r[1] + ' by SMS'" @update:model-value="S.ch[r[0]][0] = $event ? 1 : 0"/></span><span class="grid place-items-center"><Toggle :model-value="!!S.ch[r[0]][1]" :label="r[1] + ' by email'" @update:model-value="S.ch[r[0]][1] = $event ? 1 : 0"/></span></div></div>
      <div class="overflow-hidden rounded-xl border bg-card"><div class="flex items-center gap-3 px-3.5 py-3"><span class="grid h-9 w-9 place-items-center rounded-md bg-muted"><Icon name="MoonStar" :size="16" class="text-muted-foreground"/></span><span class="min-w-0 flex-1"><span class="block text-sm font-medium">Quiet hours</span><span class="block text-xs text-muted-foreground">SMS is held from 22:00 to 06:00</span></span><Toggle v-model="S.quiet" label="Quiet hours"/></div>
        <button type="button" class="press flex w-full items-center gap-3 border-t px-3.5 py-3 text-left" @click="S.sheet = 'tmpl'"><span class="grid h-9 w-9 place-items-center rounded-md bg-muted"><Icon name="MessageSquareText" :size="16" class="text-muted-foreground"/></span><span class="min-w-0 flex-1"><span class="block text-sm font-medium">Message to customers who owe</span><span class="block truncate text-xs text-muted-foreground">{{ S.tmpl }}</span></span><Icon name="ChevronRight" :size="16" class="text-muted-foreground/60"/></button></div></div></div>
    <Sheet :open="S.sheet === 'tmpl'" title="Message to customers" sub="Their name and what they owe fill in by themselves" @close="S.sheet = null"><div class="px-4 pb-4"><textarea v-model="S.tmpl" rows="4" aria-label="Message" class="flex min-h-[96px] w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm outline-none focus-visible:ring-1 focus-visible:ring-ring"></textarea><p class="mt-2 flex justify-between text-xs text-muted-foreground"><span>{{ S.tmpl.length }} characters</span><span>{{ n }} SMS each</span></p><p class="mt-3 text-xs text-muted-foreground">Use {name} and {amount}.</p></div><template #footer><Btn full @click="S.sheet = null; toast('Message saved')">Save</Btn></template></Sheet></div>` };

const Users = { components: { Header, Icon, Av, Pill, Btn, Seg, Fab, Sheet, RowsCard },
  setup() { const role = ref('Cashier'); const email = ref(''); return { USERS, role, email, S, toast }; },
  template: `<div class="relative flex min-h-0 flex-1 flex-col"><Header title="Users"/>
    <div class="scroll min-h-0 flex-1 overflow-y-auto"><div class="p-3 pb-20"><RowsCard><div v-for="(u, i) in USERS" :key="u.id" :class="['flex items-center gap-3 px-3.5 py-2.5', i ? 'border-t' : '']"><Av :c="u" :size="36"/><span class="min-w-0 flex-1"><span class="block truncate text-sm font-medium">{{ u.name }}</span><span class="block truncate text-xs text-muted-foreground">{{ u.email }} · {{ u.seen }}</span></span><span class="flex flex-col items-end gap-1"><Pill :tone="u.role === 'Owner' ? 'primary' : 'muted'">{{ u.role }}</Pill><Pill v-if="u.st === 'invited'" tone="warning">Invited</Pill></span></div></RowsCard></div></div>
    <Fab icon="UserPlus" label="Invite someone" @click="S.sheet = 'invite'"/>
    <Sheet :open="S.sheet === 'invite'" title="Invite someone" sub="They get a link by email" @close="S.sheet = null"><div class="space-y-3 px-4 pb-4"><input v-model="email" type="email" placeholder="Email address" aria-label="Email address" class="flex h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm shadow-sm outline-none focus-visible:ring-1 focus-visible:ring-ring"><Seg v-model="role" :tabs="[{ id: 'Cashier', label: 'Cashier' }, { id: 'Owner', label: 'Owner' }]"/><p class="text-xs text-muted-foreground">{{ role === 'Cashier' ? 'A cashier sells, takes payments and counts. Her changes wait for you.' : 'An owner can do everything.' }}</p></div>
      <template #footer><Btn full :disabled="!email" @click="S.sheet = null; toast('Invitation sent to ' + email)">Send invitation</Btn></template></Sheet></div>` };

const SettingsPage = { components: { Header, Icon, Toggle, Btn },
  setup() { const name = ref('Office Shop'), tz = 'Africa/Dar_es_Salaam', req = ref(true), accent = ref('blue');
    return { name, tz, req, accent, go, toast, sw: [['blue', '#2f6fe0'], ['teal', '#14937f'], ['violet', '#7c5ad8'], ['rose', '#d6456a'], ['amber', '#d06d0a']] }; },
  template: `<div class="flex min-h-0 flex-1 flex-col"><Header title="Settings"/>
    <div class="scroll min-h-0 flex-1 overflow-y-auto"><div class="space-y-4 p-3 pb-8">
      <div><p class="mb-1.5 px-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Shop</p><div class="space-y-3 rounded-xl border bg-card p-4"><label class="block text-sm font-medium">Shop name<input v-model="name" class="mt-1.5 flex h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm shadow-sm outline-none focus-visible:ring-1 focus-visible:ring-ring"></label>
        <div class="flex items-center justify-between text-sm"><span class="text-muted-foreground">Money</span><span class="font-medium">TZS, whole shillings</span></div><div class="flex items-center justify-between text-sm"><span class="text-muted-foreground">Time zone</span><span class="font-medium">{{ tz }}</span></div></div></div>
      <div><p class="mb-1.5 px-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Colour</p><div class="flex gap-3 rounded-xl border bg-card p-4"><button v-for="c in sw" :key="c[0]" type="button" :aria-label="c[0]" :aria-pressed="accent === c[0]" class="press grid h-9 w-9 place-items-center rounded-full ring-offset-2 ring-offset-background" :class="accent === c[0] ? 'ring-2 ring-foreground' : ''" :style="{ background: c[1] }" @click="accent = c[0]; toast('Colour changes for everyone')"><Icon v-if="accent === c[0]" name="Check" :size="16" class="text-white"/></button></div></div>
      <div><p class="mb-1.5 px-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Security</p><div class="flex items-center gap-3 rounded-xl border bg-card px-3.5 py-3"><span class="min-w-0 flex-1"><span class="block text-sm font-medium">Two-step sign-in for everyone</span><span class="block text-xs text-muted-foreground">A code by SMS or email after the password</span></span><Toggle v-model="req" label="Two-step sign-in for everyone"/></div></div>
      <div><p class="mb-1.5 px-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Receipt</p><button type="button" class="press flex w-full items-center gap-3 rounded-xl border bg-card px-3.5 py-3 text-left" @click="go('receiptsettings')"><span class="grid h-9 w-9 place-items-center rounded-md bg-muted"><Icon name="ReceiptText" :size="19"/></span><span class="min-w-0 flex-1"><span class="block text-sm font-medium">Receipt</span><span class="block text-xs text-muted-foreground">Logo, words and what shows on the paper</span></span><Icon name="ChevronRight" :size="18" class="text-muted-foreground"/></button></div>
      <div><p class="mb-1.5 px-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">This phone</p><div class="overflow-hidden rounded-xl border bg-card"><button type="button" class="press flex w-full items-center gap-3 px-3.5 py-3 text-left" @click="go('phonestatus')"><span class="grid h-9 w-9 place-items-center rounded-md bg-muted"><Icon name="Smartphone" :size="19"/></span><span class="min-w-0 flex-1"><span class="block text-sm font-medium">Phone status</span><span class="block text-xs text-muted-foreground">Battery, network and signal, kept for 24 hours</span></span><Icon name="ChevronRight" :size="18" class="text-muted-foreground"/></button><button type="button" class="press flex w-full items-center gap-3 border-t px-3.5 py-3 text-left" @click="go('trailmap')"><span class="grid h-9 w-9 place-items-center rounded-md bg-muted"><Icon name="MapPin" :size="19"/></span><span class="min-w-0 flex-1"><span class="block text-sm font-medium">Where this phone was</span><span class="block text-xs text-muted-foreground">A map of today's path and stops</span></span><Icon name="ChevronRight" :size="18" class="text-muted-foreground"/></button></div></div>
      <Btn full @click="toast('Settings saved')">Save settings</Btn></div></div></div>` };

/* ---- before you are in: sign in, the code, the lock, a session that ended */
const AuthShell = { props: { title: String, sub: String }, components: { Icon },
  template: `<div class="flex min-h-0 flex-1 flex-col bg-background"><div class="scroll flex min-h-0 flex-1 flex-col justify-center overflow-y-auto px-6" :style="{ paddingTop: 'var(--sa-top)', paddingBottom: 'var(--sa-bottom)' }"><div class="mb-6 flex flex-col items-center text-center"><span class="grid h-12 w-12 place-items-center rounded-xl bg-primary text-primary-foreground"><Icon name="Store" :size="22"/></span><h1 class="mt-3 text-xl font-semibold">{{ title }}</h1><p class="mt-1 text-sm text-muted-foreground">{{ sub }}</p></div><slot/></div></div>` };
const SignIn = { components: { AuthShell, Btn },
  setup() { return { S, go, tab, toast }; },
  template: `<AuthShell title="DevBiz" sub="Business at your finger tips"><form class="grid gap-4" @submit.prevent="S.route = 'twofa'">
    <label class="grid gap-1.5 text-sm font-medium">Email<input type="email" value="amina@devbiz.app" autocomplete="username" class="flex h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm shadow-sm outline-none focus-visible:ring-1 focus-visible:ring-ring"></label>
    <label class="grid gap-1.5 text-sm font-medium">Password<input type="password" value="password" autocomplete="current-password" class="flex h-9 w-full rounded-md border border-input bg-transparent px-3 text-sm shadow-sm outline-none focus-visible:ring-1 focus-visible:ring-ring"></label>
    <button type="button" class="justify-self-end text-sm font-medium text-primary" @click="toast('We email you a link')">Forgot password?</button><button class="press inline-flex h-9 w-full items-center justify-center rounded-md bg-primary text-sm font-medium text-primary-foreground shadow-sm">Sign in</button></form></AuthShell>` };
const TwoStep = { components: { AuthShell, Btn },
  setup() { const d = ref(['4', '8', '2', '', '', '']); return { d, S, tab, toast }; },
  template: `<AuthShell title="Check your email" sub="We sent a 6-digit code to a***@devbiz.app"><div class="mb-5 flex justify-center gap-1.5"><input v-for="(x, i) in d" :key="i" v-model="d[i]" maxlength="1" inputmode="numeric" :aria-label="'Digit ' + (i + 1)" class="h-12 w-10 rounded-md border border-input bg-background text-center text-lg font-semibold tnum shadow-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/30"></div>
    <Btn full @click="tab('home')">Verify</Btn><button type="button" class="mt-3 w-full text-center text-sm text-muted-foreground" @click="toast('A new code is on its way')">Resend in 0:42</button></AuthShell>` };
const LockView = { components: { Icon },
  setup() { const mode = ref('bio'), pin = ref(''); const key = (k) => { if (k === 'x') pin.value = pin.value.slice(0, -1); else if (pin.value.length < 4) pin.value += k; if (pin.value.length === 4) setTimeout(() => { pin.value = ''; tab('home'); }, 250); };
    return { mode, pin, key, S, tab }; },
  template: `<div class="flex min-h-0 flex-1 flex-col bg-background px-6 text-center" :style="{ paddingTop: 'calc(48px + var(--sa-top))', paddingBottom: 'calc(20px + var(--sa-bottom))' }">
    <span class="mx-auto grid h-14 w-14 place-items-center rounded-xl bg-primary text-primary-foreground"><Icon name="Store" :size="26"/></span><h1 class="mt-4 text-xl font-semibold">DevBiz is locked</h1><p class="mt-1 text-sm text-muted-foreground">{{ mode === 'bio' ? 'Use your fingerprint to open it.' : 'Enter your PIN.' }}</p>
    <div v-if="mode === 'pin'" class="mt-6 flex justify-center gap-3"><span v-for="i in 4" :key="i" :class="['h-3 w-3 rounded-full border-2 border-primary', pin.length >= i ? 'bg-primary' : '']"></span></div>
    <div class="min-h-0 flex-1"></div>
    <div v-if="mode === 'pin'" class="mx-auto mb-4 grid w-full max-w-[260px] grid-cols-3 gap-3"><button v-for="k in ['1','2','3','4','5','6','7','8','9','','0','x']" :key="k" type="button" :disabled="k === ''" :class="['press grid h-12 place-items-center rounded-full text-lg font-semibold', k === '' ? 'invisible' : 'border bg-card']" :aria-label="k === 'x' ? 'Delete' : k" @click="key(k)"><Icon v-if="k === 'x'" name="Delete" :size="20"/><template v-else>{{ k }}</template></button></div>
    <button v-if="mode === 'bio'" type="button" class="press mx-auto inline-flex h-9 w-full max-w-[260px] items-center justify-center gap-2 rounded-md bg-primary text-sm font-medium text-primary-foreground shadow-sm" @click="tab('home')"><Icon name="Fingerprint" :size="18"/>Use fingerprint</button>
    <button type="button" class="mt-3 text-sm font-medium text-primary" @click="mode = mode === 'bio' ? 'pin' : 'bio'">{{ mode === 'bio' ? 'Use PIN instead' : 'Use fingerprint instead' }}</button><button type="button" class="mt-2 text-xs text-muted-foreground" @click="S.route = 'login'">Sign out</button></div>` };
const SessionEnded = { components: { AuthShell, Icon, Btn },
  setup() { return { S }; },
  template: `<AuthShell title="You were signed out" sub="For safety, DevBiz asks you to sign in again. What you had open is kept on this phone for this account."><Btn full @click="S.route = 'login'"><Icon name="LogIn" :size="16"/>Sign in again</Btn></AuthShell>` };

/* the phone's states: no signal, an update */
const NetBar = { components: { Icon }, setup() { return { S, toast }; },
  template: `<div v-if="S.net === 'offline'" class="relative z-[55] flex shrink-0 items-center gap-2 bg-warning/15 px-3 py-1.5 text-xs text-warning" :style="{ paddingTop: 'calc(6px + var(--sa-real))' }" role="status"><Icon name="WifiOff" :size="14"/><span class="flex-1">Offline · showing figures from 3 min ago. Nothing can be saved.</span><button type="button" class="font-semibold underline" @click="S.net = 'online'; toast('Updated just now')">Try again</button></div>` };
const UpdateBar = { components: { Icon }, setup() { return { S, toast }; },
  template: `<div v-if="S.update === 'available'" class="relative z-[54] flex shrink-0 items-center gap-2 border-b bg-primary/10 px-3 pb-2 text-sm" :style="{ paddingTop: S.net === 'offline' ? '8px' : 'calc(8px + var(--sa-real))' }" role="status"><Icon name="Download" :size="16" class="text-primary"/><span class="flex-1">A new version of DevBiz is ready</span><button type="button" class="h-8 rounded-md px-2 text-xs font-medium text-muted-foreground" @click="S.update = null">Later</button><button type="button" class="h-8 rounded-md bg-primary px-3 text-xs font-medium text-primary-foreground" @click="toast('Opening the download')">Update</button></div>` };
const UpdateRequired = { components: { Icon, Btn }, setup() { return { S, toast }; },
  template: `<div v-if="S.update === 'required'" class="absolute inset-0 z-[110] flex flex-col items-center justify-center bg-background px-6 text-center"><span class="grid h-12 w-12 place-items-center rounded-xl bg-primary text-primary-foreground"><Icon name="Store" :size="22"/></span><h2 class="mt-4 text-xl font-semibold">Update DevBiz to keep going</h2><p class="mt-1 text-sm text-muted-foreground">This version no longer works with the server.</p><div class="mt-5 w-full"><Btn full @click="toast('Opening the download')"><Icon name="Download" :size="16"/>Update now</Btn></div><p class="mt-2 text-xs text-muted-foreground tnum">Version 1.0.2 · needs 1.1.0 or newer</p></div>` };
